// Center column of the WorkbenchLM: a lightweight chatbot interface.
// Talks to the FastAPI inference gateway (POST /chat); the gateway forwards
// MCP calls + the LLM round trip and returns a single assistant message.
//
// This file is the orchestrator — state, send pipeline, and layout. The
// individual pieces (bubble / meta row / empty state / input bar / chat
// download / per-turn enrichment) live as siblings under
// `./workbench-lm-chat/` so each concern stays small and testable.
//
// Session lifecycle: a session_id is generated by the gateway on the first
// turn and reused for the lifetime of the page (or until the user changes
// datapack). Switching datapacks resets the chat.

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { AlertCircle, Download } from "lucide-react";
import { getInferenceGatewayErrorMessage, postChat } from "@/lib/inferenceGateway";
import type { DatapackThreadMessage } from "@/lib/api/mekoApi";
import { useAccountUsage, ACCOUNT_USAGE_QUERY_KEY } from "@/hooks/useAccountUsage";
import { useCurrentUser } from "@/hooks/useCurrentUser";
import { FREE_TIER_BLOCKED_MESSAGES, getFreeTierStatus } from "@/lib/freeTier";
import { FreeTierLimitBanner } from "@/lib/freeTierBanner";
import { queryClient } from "@/lib/queryClient";
import type { DatapackShareGrant } from "@/lib/datapackShareGrants";
import { TELEMETRY_CLIENT_WORKBENCH, TELEMETRY_EVENTS } from "@/lib/telemetry/events";
import { trackEvent } from "@/lib/telemetry/rudderstack";
import { ChatBubble, ThinkingBubble } from "./workbench-lm-chat/ChatBubble";
import { ChatInput } from "./workbench-lm-chat/ChatInput";
import { EmptyState } from "./workbench-lm-chat/EmptyState";
import { downloadChat } from "./workbench-lm-chat/downloadChat";
import type { KnowledgeReadiness, Message } from "./workbench-lm-chat/types";

// Re-export so existing call sites (`WorkbenchLMPage`) keep working without
// path changes. The split is an internal refactor.
export type { KnowledgeReadiness } from "./workbench-lm-chat/types";

/** ── Dev toggle ───────────────────────────────────────────────────────────
 * When `true`, the chat input stays disabled until the active datapack has at
 * least one knowledge doc in COMPLETED state. Flip to `false` to chat against
 * an empty KB (useful for testing the gateway / LLM round-trip without
 * uploading first). Default `true` for production-ish UX.
 */
const REQUIRE_KNOWLEDGE_BEFORE_CHAT = false;

export type WorkbenchLMChatProps = {
  datapackName: string | null;
  datapackId: string | null;
  /** account_id of the signed-in user; required by the gateway. */
  userId: string | null;
  /** Bearer token the gateway forwards to MCP. v1 sources it from env via WorkbenchLMPage. */
  userToken: string | null;
  /** Knowledge readiness for the active datapack. Chat is gated on `ready`. */
  knowledgeReadiness: KnowledgeReadiness;
  /** True when the bundled travel sample (`europe-travel-guide.md`) is in
   *  the KB — drives the EmptyState example prompts. */
  hasSampleKnowledge: boolean;
  /** Fired after each successful turn so the right rail can refetch memories/conversations. */
  onTurnComplete?: () => void;
  /** Fired when the user clicks "View trace" on an assistant message.
   *  Parent owns the trace drawer state so it can persist across re-renders. */
  onOpenTrace?: (messageId: string, conversationId: string) => void;
  /** id of a previous conversation the user is resuming. Set by the
   *  page after the user picks an entry from the "Previous chats"
   *  dropdown; `null` means a fresh chat. When set, `loadedThread`
   *  carries the existing messages and every new turn we send to the
   *  gateway includes this id so the backend appends to the same
   *  conversation row instead of creating a new one. */
  loadedConversationId?: string | null;
  /** Thread fetched from `getDatapackConversation` when the user picks
   *  a previous chat. Each entry becomes a user + assistant bubble.
   *  `null` when no resume is in flight. */
  loadedThread?: DatapackThreadMessage[] | null;
  /** Langfuse project id for the resumed conversation (from the same
   *  `getDatapackConversation` response that produced `loadedThread`).
   *  Forwarded into each historical bubble's DecisionTrace so its
   *  "open in Langfuse" deep-links resolve. */
  loadedLangfuseProjectId?: string | null;
  /** Signed-in user's role on this datapack — telemetry `role` on conversation_started. */
  datapackGrant?: DatapackShareGrant | null;
  /** Count of the user's existing conversations in this datapack, for total_conversations / is_first. */
  conversationCount?: number;
};

export function WorkbenchLMChat({
  datapackName,
  datapackId,
  userId,
  userToken,
  knowledgeReadiness,
  hasSampleKnowledge,
  onTurnComplete,
  onOpenTrace,
  loadedConversationId = null,
  loadedThread = null,
  loadedLangfuseProjectId = null,
  datapackGrant = null,
  conversationCount = 0,
}: WorkbenchLMChatProps) {
  const { data: currentUser } = useCurrentUser();
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState("");
  const [sessionId, setSessionId] = useState<string | null>(null);
  // Stored at the session level — same conversation_id for every assistant
  // message in this chat (only changes on datapack switch / fresh session).
  const [conversationId, setConversationId] = useState<string | null>(null);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const endRef = useRef<HTMLDivElement>(null);

  // Reset chat state whenever the active datapack changes — keeps the
  // server-side conversation pinned to one datapack and avoids "memories
  // from datapack A leaking into datapack B" surprises.
  useEffect(() => {
    setMessages([]);
    setSessionId(null);
    setConversationId(null);
    setInput("");
    setError(null);
  }, [datapackId]);

  // Resume / reset the chat based on the page's "loaded thread" state.
  //
  // Three transitions land here:
  //   a) Page hands us a resumed thread (user picked from dropdown) →
  //      synthesise bubbles, adopt the conversation_id so the next
  //      /chat call carries it (gateway then skips conversation_create
  //      and appends to the same Langfuse row).
  //   b) Page clears the resume state (user clicked "+ New chat") →
  //      wipe the chat back to empty so the EmptyState shows. Without
  //      this, the previous thread would stay rendered and the next
  //      message would append to a phantom history.
  //   c) Initial mount before any resume → both null, branch (b) runs
  //      against already-empty state. Idempotent, no flicker.
  //
  // Old turns deliberately leave `memoryHits` / `kbHits` /
  // `processingSteps` undefined on the synthesised `Message`: the
  // historical agentic thinking block is rendered NOT from these
  // fields but from the raw `DatapackThreadMessage` via `DecisionTrace`
  // (see `traceByMessageId` below + the bubble render). That component
  // reads `reasoning` / `plan` / `memory_hits` / `kb_hits` /
  // `processing_steps` straight off the loaded thread — the same data
  // the Conversations viewer renders — and self-hides if a given turn
  // has none. Live turns use the SAME DecisionTrace, lazily fetched by
  // message_id on expand (see LiveDecisionTrace). "View trace" still
  // works on every assistant bubble because `langfuseMessageId` is
  // preserved.
  useEffect(() => {
    if (!loadedConversationId || !loadedThread) {
      // Branch (b)/(c): fresh chat requested. Mirror the datapack-change
      // reset above — chatting forward from here mints a brand-new
      // conversation_id on the gateway side.
      setMessages([]);
      setConversationId(null);
      setSessionId(null);
      setInput("");
      setError(null);
      return;
    }
    const synthesised: Message[] = [];
    for (const m of loadedThread) {
      synthesised.push({
        id: `loaded-user-${m.message_id}`,
        role: "user",
        content: m.input ?? "",
      });
      synthesised.push({
        id: `loaded-assistant-${m.message_id}`,
        role: "assistant",
        content: m.output ?? "",
        langfuseMessageId: m.message_id,
        latencyMs: m.latency_ms ?? undefined,
        memoriesExtracted: m.memories_extracted ?? undefined,
        llmCalls: m.llm_calls ?? undefined,
        // memoryHits / kbHits / processingSteps intentionally left
        // undefined — historical turns render DecisionTrace from the raw
        // thread message (traceByMessageId), not from these fields.
      });
    }
    setMessages(synthesised);
    setConversationId(loadedConversationId);
    // Fresh in-memory session: the gateway will mint a new session_id
    // on the next turn, but `conversation_id` from the body keeps the
    // server-side conversation pinned to the resumed thread.
    setSessionId(null);
    setInput("");
    setError(null);
  }, [loadedConversationId, loadedThread]);

  // Auto-scroll to the latest message / "thinking" indicator.
  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: "smooth", block: "end" });
  }, [messages, sending]);

  // When the dev toggle says we don't need knowledge first, treat readiness
  // as "ready" regardless of the actual KB state.
  const gatedReadiness: KnowledgeReadiness = REQUIRE_KNOWLEDGE_BEFORE_CHAT
    ? knowledgeReadiness
    : "ready";

  // Free-tier usage caps (WorkbenchLM conversations + token burn).
  // Surfaced as the highest-priority blockers so a user who's hit the
  // cap sees the upgrade message instead of a lower-priority hint like
  // "Select a datapack" — the cap matters even after they've picked one.
  const { data: accountUsage } = useAccountUsage();
  const freeTier = getFreeTierStatus(accountUsage, currentUser?.user_type);

  // Order matters: report the blocker the user can act on first.
  // free-tier caps → datapack → account → token → knowledge readiness.
  const blockedReason = freeTier.hasHitNumConversations
    ? FREE_TIER_BLOCKED_MESSAGES.conversations
    : freeTier.hasHitTokenBurn
      ? FREE_TIER_BLOCKED_MESSAGES.tokenBurn
      : !datapackName
        ? "Select a datapack from the header to start chatting."
        : !userId
          ? "Loading your account…"
          : !userToken
            ? "MCP token unavailable. Set VITE_MEKO_MCP_BEARER (dev) or wire token retrieval."
            : gatedReadiness === "loading"
              ? "Checking your knowledge base…"
              : gatedReadiness === "absent"
                ? "Upload a file under Knowledge to start chatting."
                : gatedReadiness === "processing"
                  ? "Knowledge is processing — chat will enable when it's ready."
                  : null;
  const inputDisabled = blockedReason !== null || sending;

  const send = useCallback(
    async (text: string, opts?: { bypassConversationCache?: boolean }) => {
      const trimmed = text.trim();
      if (
        !trimmed ||
        !datapackId ||
        !userId ||
        !userToken ||
        sending ||
        gatedReadiness !== "ready"
      ) {
        return;
      }
      const bypass = opts?.bypassConversationCache ?? false;
      // A brand-new conversation is being started when neither id exists yet.
      const isFirstMessage = conversationId === null && sessionId === null;

      setError(null);
      const userMsg: Message = {
        id: crypto.randomUUID(),
        role: "user",
        content: trimmed,
      };
      // Optimistically append the user turn so it shows up immediately.
      setMessages((prev) => [...prev, userMsg]);
      setInput("");
      setSending(true);

      try {
        const resp = await postChat({
          message: trimmed,
          user_token: userToken,
          user_id: userId,
          // First call: send undefined so the gateway mints a session_id.
          // Subsequent calls: reuse what the gateway returned.
          session_id: sessionId ?? undefined,
          datapack_id: datapackId ?? undefined,
          // Carry the active conversation_id when present so the
          // gateway appends to that conversation instead of minting a
          // new one. Always set after the first turn of any session
          // (gateway responses populate it); also set when the user
          // resumed a previous chat from the dropdown.
          conversation_id: conversationId ?? undefined,
          // Set by the "Regenerate with full search" button to force the
          // full memory + KB + LLM path instead of reusing a cached answer.
          bypass_conversation_cache: bypass || undefined,
        });
        if (resp.session_id) setSessionId(resp.session_id);
        if (resp.conversation_id) setConversationId(resp.conversation_id);
        // conversation_started: only on the first turn, once the gateway has
        // minted the new conversation_id.
        if (isFirstMessage && resp.conversation_id) {
          trackEvent(TELEMETRY_EVENTS.CONVERSATION_STARTED, {
            email: currentUser?.email,
            conversation_id: resp.conversation_id,
            datapack_id: datapackId ?? undefined,
            client: TELEMETRY_CLIENT_WORKBENCH,
            role: datapackGrant ?? undefined,
            total_conversations: conversationCount + 1,
            is_first: conversationCount === 0,
          });
        }
        // A conversation-cache hit shows up as a `conversation_summarize` step
        // in the gateway's per-turn timeline — detect it immediately (no need
        // to wait for the Langfuse decision-trace fetch) so the bubble can
        // offer "Regenerate with full search".
        const answeredFromCache = (resp.processing_steps ?? []).some(
          (s) => s.name === "conversation_summarize" && s.status === "ok",
        );
        const assistantMsgId = crypto.randomUUID();
        const assistantMsg: Message = {
          id: assistantMsgId,
          role: "assistant",
          content: resp.message,
          // Empty when the gateway couldn't capture it — that's fine; the
          // trace block + "View trace" just won't render for that bubble.
          // The turn's retrieval / steps / telemetry are no longer stored
          // on the message: the bubble renders them via the per-message
          // `getDatapackMessageDecisionTrace` query (react-query cached),
          // so the gateway's `memory_hits` / `kb_hits` / `processing_steps`
          // / `memory_context` / `kb_context` go unused here.
          langfuseMessageId: resp.message_id || undefined,
          // Only mark as cache-answered when this turn DIDN'T already bypass
          // the cache — a re-answer should never offer to regenerate again.
          answeredFromCache: answeredFromCache && !bypass,
          sourceUserMessage: answeredFromCache && !bypass ? trimmed : undefined,
        };
        setMessages((prev) => [...prev, assistantMsg]);
        onTurnComplete?.();
        // Bumps num_conversations + token_burn on the BE. Invalidate
        // here so the cap-derived `blockedReason` re-evaluates on the
        // next render instead of waiting out the 60s staleTime — gives
        // the user immediate feedback if their next turn would put
        // them over.
        void queryClient.invalidateQueries({ queryKey: [ACCOUNT_USAGE_QUERY_KEY] });
      } catch (err) {
        setError(getInferenceGatewayErrorMessage(err));
      } finally {
        setSending(false);
      }
    },
    [
      datapackId,
      userId,
      userToken,
      sending,
      sessionId,
      conversationId,
      gatedReadiness,
      onTurnComplete,
      datapackGrant,
      conversationCount,
      currentUser?.email,
    ],
  );

  const handleSubmit = useCallback(() => {
    if (inputDisabled || input.trim().length === 0) return;
    void send(input);
  }, [inputDisabled, input, send]);

  // message_id → raw thread message, for the resumed conversation only.
  // Live bubbles aren't in here (their langfuseMessageId comes from the
  // fresh POST /chat response, not `loadedThread`), so ChatBubble routes
  // them to LiveDecisionTrace (lazy fetch by message_id) instead.
  const traceByMessageId = useMemo(() => {
    const map = new Map<string, DatapackThreadMessage>();
    for (const m of loadedThread ?? []) {
      if (m.message_id) map.set(m.message_id, m);
    }
    return map;
  }, [loadedThread]);

  const canDownload = messages.length > 0;
  const handleDownload = useCallback(() => {
    if (!canDownload) return;
    downloadChat({
      messages,
      datapackName,
      sessionId,
      conversationId,
    });
  }, [canDownload, messages, datapackName, sessionId, conversationId]);

  return (
    <section className="flex min-h-0 flex-col border-r border-border bg-background">
      {/* Compact toolbar — appears as soon as the conversation has at least
          one turn. Right-aligned Download button only for now. Hidden in
          the empty state so the welcome / example-prompts UX isn't crowded. */}
      {canDownload ? (
        <div className="flex items-center justify-end border-b border-border/40 bg-background/60 px-4 py-1.5">
          <button
            type="button"
            onClick={handleDownload}
            className="inline-flex items-center gap-1.5 rounded-md border border-border bg-card px-2.5 py-1 text-xs text-muted-foreground transition-colors hover:border-border/80 hover:text-foreground"
            aria-label="Download chat as text"
            title="Download this chat as a .txt file"
          >
            <Download className="h-3.5 w-3.5" aria-hidden />
            Download
          </button>
        </div>
      ) : null}

      {/* Scrollable message area */}
      <div className="flex-1 min-h-0 overflow-y-auto">
        {messages.length === 0 ? (
          <EmptyState
            disabled={inputDisabled || !datapackName}
            onPick={(prompt) => void send(prompt)}
            showSamplePrompts={hasSampleKnowledge}
          />
        ) : (
          <div className="mx-auto w-full max-w-3xl space-y-5 px-6 py-6">
            {messages.map((m) => {
              // Historical assistant turns match a loaded thread row by
              // message_id → render the full DecisionTrace. Live turns
              // (and user bubbles) miss the map and keep their existing
              // rendering path inside ChatBubble.
              const traceMessage =
                m.role === "assistant" && m.langfuseMessageId
                  ? traceByMessageId.get(m.langfuseMessageId)
                  : undefined;
              return (
                <ChatBubble
                  key={m.id}
                  message={m}
                  onOpenTrace={
                    m.langfuseMessageId && conversationId && onOpenTrace
                      ? () => onOpenTrace(m.langfuseMessageId!, conversationId)
                      : undefined
                  }
                  traceMessage={traceMessage}
                  conversationId={conversationId ?? undefined}
                  langfuseProjectId={loadedLangfuseProjectId ?? undefined}
                  datapackId={datapackId}
                  onRegenerate={
                    m.role === "assistant" && m.answeredFromCache && m.sourceUserMessage && !sending
                      ? () => void send(m.sourceUserMessage!, { bypassConversationCache: true })
                      : undefined
                  }
                  datapackName={datapackName}
                />
              );
            })}
            {sending && <ThinkingBubble />}
            <div ref={endRef} />
          </div>
        )}
      </div>

      {error && (
        <div className="mx-auto w-full max-w-3xl px-6 pb-2">
          <div className="flex items-start gap-2 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-700 dark:text-red-300">
            <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" aria-hidden />
            <span className="break-words">{error}</span>
          </div>
        </div>
      )}

      {freeTier.hasHitNumConversations ? (
        <FreeTierLimitBanner kind="conversations" className="mx-1" />
      ) : freeTier.hasHitTokenBurn ? (
        <FreeTierLimitBanner kind="tokenBurn" className="mx-1" />
      ) : null}

      <ChatInput
        value={input}
        onChange={setInput}
        onSubmit={handleSubmit}
        disabled={inputDisabled}
        sending={sending}
        blockedReason={blockedReason}
      />
    </section>
  );
}
